const input = $input.first().json;
const cookies = JSON.stringify(input.cookies || []);
const localStorage = JSON.stringify(input.localStorage || {});
const lastUrl = input.url || 'https://app.cotadorsimplificado.com.br';
const fezLogin = input.fezLogin;
const logAnterior = input.log || [];

const code = `export default async function ({ page }) {
  const log = ${JSON.stringify(logAnterior)};
  const wait = (ms) => new Promise(r => setTimeout(r, ms));
  const cookies = ${cookies};
  const ls = ${localStorage};
  const fezLogin = ${fezLogin};

  try {
    await page.setViewport({ width: 1280, height: 800 });
    log.push('Restaurando sessao...');
    await page.goto('${lastUrl}', { waitUntil: 'domcontentloaded', timeout: 30000 });
    if (cookies.length > 0) await page.setCookie(...cookies);
    await page.evaluate((ls) => {
      for (const [key, value] of Object.entries(ls)) {
        window.localStorage.setItem(key, value);
      }
    }, ls);
    await page.reload({ waitUntil: 'networkidle2' });
    await wait(2000);

    const loginBtn = await page.$('#email_principal');
    if (loginBtn && !fezLogin) {
      log.push('ERRO: Sessao expirada!');
      return { success: false, error: 'Sessao expirada', log, sessaoExpirada: true };
    }
    log.push('Sessao OK');

    log.push('Clicando PME...');
    await page.evaluate(() => {
      const pme = [...document.querySelectorAll('.clickable-element')].find(e => e.textContent.includes('PME') && e.textContent.includes('29'));
      if (pme) pme.click();
    });
    await wait(2000);
    log.push('PME OK');

    log.push('Preenchendo nome...');
    await page.waitForSelector('#id-nomelead', { timeout: 10000 });
    await page.click('#id-nomelead');
    await page.type('#id-nomelead', 'teste', { delay: 30 });
    log.push('Nome OK');

    log.push('Avancando 1...');
    await page.evaluate(() => {
      const btn = [...document.querySelectorAll('button')].find(b => b.textContent.includes('Avan'));
      if (btn) btn.click();
    });
    await wait(2000);
    log.push('Avancar 1 OK');

    log.push('Preenchendo cidade...');
    await page.waitForSelector('#cidade_nome', { timeout: 10000 });
    await page.click('#cidade_nome');
    await page.type('#cidade_nome', 'recife', { delay: 30 });
    await wait(1500);
    await page.keyboard.press('ArrowDown');
    await wait(300);
    await page.keyboard.press('Enter');
    await wait(1500);
    log.push('Cidade OK');

    log.push('Selecionando empresa...');
    await page.evaluate(() => {
      const sel = document.querySelector('select');
      if (sel) {
        const opt = [...sel.options].find(o => o.textContent.includes('MEI'));
        if (opt) {
          sel.value = opt.value;
          sel.dispatchEvent(new Event('change', { bubbles: true }));
        }
      }
    });
    await wait(1000);
    log.push('Empresa OK');

    log.push('Avancando 2...');
    await page.evaluate(() => {
      const btn = [...document.querySelectorAll('button')].find(b => b.textContent.includes('Avan'));
      if (btn) btn.click();
    });
    await wait(2000);
    log.push('Avancar 2 OK');

    log.push('Preenchendo faixas...');
    const baseSelector = '#index > div > div > div > div.bubble-element.Group.cnaTaBaK.bubble-r-container.flex.column > div.bubble-element.Group.coaJet.bubble-r-container.flex.column > div.bubble-element.Group.cnaTaAaH.bubble-r-container.flex.row > div.bubble-element.CustomElement.cocyh.bubble-r-container.flex.column > div.bubble-element.RepeatingGroup.cocyn.bubble-rg > div.bubble-element.group-item.bubble-r-container.flex.column.entry-';
    let preenchidas = 0;
    for (let i = 1; i <= 10; i++) {
      try {
        const sel = baseSelector + i + ' > input';
        await page.waitForSelector(sel, { timeout: 2000 });
        await page.click(sel);
        await page.type(sel, '1');
        preenchidas++;
      } catch(e) {}
    }
    log.push('Faixas: ' + preenchidas);

    return { success: true, log, url: page.url() };
  } catch (error) {
    return { success: false, error: error.message, log };
  }
}`;

return [{ json: { code } }];

